ont-size:16px;margin:4px 0 0;letter-spacing:-.3px}.factory-header h2 small{font-size:10px;font-weight:400;color:#768499;letter-spacing:0}.slots-available{font:8px var(--mono);color:#8f9eb2;letter-spacing:.6px}.factory-layout{display:grid;grid-template-columns:minmax(0,1fr) 250px;gap:12px}.facility-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.facility-card{height:92px;background:linear-gradient(140deg,#111a26,#0d141e);border:1px solid #202c3b;border-radius:5px;padding:10px 11px;position:relative;overflow:hidden}.facility-card:after{content:'';height:1px;position:absolute;bottom:0;left:0;right:0;background:linear-gradient(90deg,#80c5a7,var(--accent,#8bb9f5));opacity:.6}.facility-card.empty{border-style:dashed;background:#0b1119;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:5px;color:#526174}.facility-card.empty:after{display:none}.empty-plus{font-size:16px;line-height:1;color:#697a8f}.facility-card.empty small{font:8px var(--mono);letter-spacing:.6px}.facility-top{display:flex;justify-content:space-between;align-items:start}.facility-icon{font-size:16px;color:var(--accent,#e0b475);background:#22202a;width:27px;height:27px;border-radius:5px;display:grid;place-items:center}.facility-badge{font:7px var(--mono);color:#78c7a2;letter-spacing:.4px}.facility-card h3{font-size:10px;margin:5px 0 3px;font-weight:600}.facility-output{font:8px var(--mono);color:#8090a4}.facility-state{position:absolute;right:10px;bottom:11px;color:#6c7d91;font:7px var(--mono)}.build-menu{border:1px solid #243246;border-radius:5px;background:#0e1723;padding:11px}.build-menu-title{display:flex;justify-content:space-between;font:8px var(--mono);letter-spacing:.8px;color:#a5b2c3;padding-bottom:7px}.blueprint-icon{font-size:13px;color:#8eb5ed}.build-option{display:grid;grid-template-columns:24px 1fr auto;align-items:center;gap:7px;width:100%;text-align:left;background:transparent;border:0;border-top:1px solid #202b39;padding:7px 0;cursor:pointer}.build-option:hover:not(:disabled){background:#152131}.build-option:disabled{opacity:.42;cursor:not-allowed}.build-option .option-icon{font-size:14px;color:#e2b477}.build-option:nth-of-type(3) .option-icon{color:#97b9e8}.option-info{display:flex;flex-direction:column;gap:3px}.option-info b{font-size:9px;font-weight:600}.option-info small{font:7px var(--mono);color:#8190a4}.option-cost{display:flex;flex-direction:column;align-items:end;gap:2px;font:7px var(--mono);color:#b4a07e;white-space:nowrap}.build-footnote{font-size:8px;color:#76859a;padding-top:5px;border-top:1px solid #202b39;line-height:1.4}.build-footnote span{color:#8ca9ce;margin-right:4px}footer{display:flex;justify-content:space-between;border-top:1px solid #1c2734;margin-top:20px;padding:12px 0 18px;font:8px var(--mono);letter-spacing:.6px;color:#5e6d80}footer i{font-style:normal;color:#a88458;padding:0 3px}footer b{font-size:10px;color:#d4a866;margin-left:4px}.toast{position:fixed;left:50%;bottom:22px;z-index:10;transform:translate(-50%,20px);padding:10px 15px;border:1px solid #3b4e60;background:#131e2b;color:#e3edf8;border-radius:5px;font:11px var(--mono);box-shadow:0 8px 30px #0009;opacity:0;pointer-events:none;transition:all .25s}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:900px){.app-shell{padding:0 22px}.resource-strip{grid-template-columns:repeat(3,1fr);height:auto;padding:8px 0;row-gap:12px}.resource-item{padding:0 10px}.resource-item:nth-child(3){border-right:0}.resource-item:first-child{padding-left:10px}.energy-readout{padding-left:10px}.dashboard{grid-template-columns:minmax(0,1.4fr) minmax(235px,.8fr)}.factory-layout{grid-template-columns:minmax(0,1fr) 230px}.facility-grid{grid-template-columns:repeat(2,1fr)}.facility-card{height:87px}.system-visual{height:230px}}
@media(max-width:640px){.app-shell{padding:0 14px}.topbar{height:62px}.save-state{font-size:8px;gap:6px}.resource-strip{grid-template-columns:repeat(2,1fr);padding:10px 0;gap:11px 0}.resource-item{padding:0 7px;border-right:0}.resource-item:first-child{padding-left:7px}.resource-item em{font-size:8px}.resource-item small{font-size:8px}.resource-item b{font-size:14px}.resource-glyph{width:26px;height:26px}.energy-readout{padding:0 7px}.page-heading{align-items:flex-start;flex-direction:column;gap:15px;padding:22px 0 16px}.page-heading h1{font-size:28px}.objective-card{width:100%;min-width:0}.dashboard{grid-template-columns:1fr}.side-column{display:grid;grid-template-columns:1fr 1fr;align-items:start}.reset-button{grid-column:2;justify-self:end}.system-visual{height:230px}.factory-section{margin-top:18px}.factory-header h2{font-size:14px}.factory-header h2 small{display:block;margin-top:3px}.factory-layout{grid-template-columns:1fr}.facility-grid{grid-template-columns:repeat(2,1fr);gap:7px}.facility-card{height:89px}.build-menu{display:grid;grid-template-columns:1fr 1fr;column-gap:10px}.build-menu-title,.build-footnote{grid-column:1/-1}.build-option{padding:8px 2px}.ring-labels{gap:9px}.ring-labels span{font-size:7px}.ring-labels span b{display:none}.deploy-row{gap:9px}.deploy-row>div small{max-width:190px;line-height:1.4}.primary-button{gap:8px;padding:10px;font-size:8px}.intel-panel,.log-panel{padding:12px}.intel-note{gap:5px;padding:6px}.intel-note small{font-size:7px}.intel-note b{font-size:8px}.activity-item{grid-template-columns:30px 1fr}.activity-item p{font-size:8px}footer{font-size:7px;gap:8px}footer span:last-child{text-align:right}}

(() => {
  const SAVE_KEY = 'helios-foundry-save-v1';
  const TOTAL_SEGMENTS = 72;
  const recipes = {
    iron: {name:'Iron extractor', icon:'▰', color:'#d9a563', output:'IRON ORE', rate:1.25, power:5, cost:{iron:18,silicon:8}, description:'+1.25 ore / sec'},
    silicon: {name:'Silicon harvester', icon:'◆', color:'#9bbdef', output:'SILICON', rate:1.05, power:5, cost:{iron:14,silicon:12}, description:'+1.05 silicon / sec'},
    foundry: {name:'Alloy foundry', icon:'⬡', color:'#d0a6e2', output:'STRUCTURAL ALLOY', rate:.48, power:10, cost:{iron:24,silicon:10}, description:'Smelts iron into alloy'},
    solar: {name:'Solar forge', icon:'✦', color:'#f0ce72', output:'SOLAR CELLS', rate:.65, power:7, cost:{iron:18,silicon:15}, description:'Prints cells from silicon'},
    circuit: {name:'Circuit printer', icon:'▦', color:'#79d1a7', output:'PROCESSORS', rate:.18, power:8, cost:{iron:20,silicon:20}, description:'Builds orbital processors'},
    assembler: {name:'Shell assembler', icon:'◈', color:'#8de0da', output:'SHELL SEGMENTS', rate:.18, power:12, cost:{iron:25,silicon:20}, description:'Assembles Dyson shell segments'}
  };
  const initialState = () => ({resources:{iron:70,silicon:50,alloy:0,cells:0,processors:0,segments:0}, buildings:['iron','silicon',null,null,null,null], panels:0, cycle:1, elapsed:0, eventLog:[], muted:false});
  let state;
  try { state = Object.assign(initialState(), JSON.parse(localStorage.getItem(SAVE_KEY) || '{}')); } catch { state = initialState(); }
  state.resources = Object.assign(initialState().resources, state.resources || {});
  state.buildings = Array.isArray(state.buildings) ? state.buildings.slice(0,6) : initialState().buildings;
  while (state.buildings.length < 6) state.buildings.push(null);
  state.eventLog = Array.isArray(state.eventLog) ? state.eventLog : [];
  let lastTime = performance.now(), saveTimer = 0, toastTimer;
  const $ = id => document.getElementById(id);
  const names = {iron:'iron ore',silicon:'silicon',alloy:'structural alloy',cells:'solar cells',processors:'processors',segments:'shell segments'};
  const ratesEl = {iron:$('iron-rate'),silicon:$('silicon-rate'),alloy:$('alloy-rate'),cells:$('cells-rate'),processors:$('processors-rate')};
  const number = n => Number(n).toLocaleString('en-US',{maximumFractionDigits:n < 10 ? 1 : 0});
  function log(message, timeLabel='SYS') {
    const stamp = timeLabel === 'SYS' ? `${String(Math.floor(state.elapsed/60)).padStart(2,'0')}:${String(Math.floor(state.elapsed%60)).padStart(2,'0')}` : timeLabel;
    state.eventLog.unshift({stamp,message}); state.eventLog = state.eventLog.slice(0,4); renderLog(); save();
  }
  function renderLog() {
    $('activity-list').innerHTML = state.eventLog.map(e=>`<div class="activity-item"><time>${e.stamp}</time><p>${e.message}</p></div>`).join('') || '<div class="activity-item"><time>00:00</time><p>Foundry network initialized.</p></div>';
    $('log-count').textContent = String(Math.max(1,state.eventLog.length)).padStart(2,'0');
  }
  function canAfford(cost) { return Object.entries(cost).every(([key,value])=>state.resources[key] >= value); }
  function renderBuildOptions() {
    $('build-options').innerHTML = Object.entries(recipes).map(([key,r])=>{
      const available=state.buildings.includes(null), affordable=canAfford(r.cost);
      return `<button class="build-option" data-build="${key}" ${!available||!affordable?'disabled':''} title="${r.description}"><span class="option-icon" style="color:${r.color}">${r.icon}</span><span class="option-info"><b>${r.name}</b><small>${r.description}</small></span><span class="option-cost"><span>${r.cost.iron} Fe</span><span>${r.cost.silicon} Si</span></span></button>`;
    }).join('');
    document.querySelectorAll('[data-build]').forEach(button=>button.addEventListener('click',()=>build(button.dataset.build)));
  }
  function renderBuildings() {
    $('facility-grid').innerHTML=state.buildings.map((type,index)=>{
      if(!type || !recipes[type]) return `<div class="facility-card empty"><span class="empty-plus">＋</span><small>OPEN SLOT 0${index+1}</small></div>`;
      const r=recipes[type];
      const output=type==='foundry'?'1.8 Fe → 0.48 alloy/s':type==='solar'?'1.0 Si → 0.65 cells/s':type==='circuit'?'0.55 Si + 0.18 alloy → chips':type==='assembler'?'2.5 alloy + cells + chips → shell':r.description;
      return `<div class="facility-card" style="--accent:${r.color}"><div class="facility-top"><span class="facility-icon" style="color:${r.color}">${r.icon}</span><span class="facility-badge">● ONLINE</span></div><h3>${r.name}</h3><span class="facility-output">${output}</span><span class="facility-state">AUTO</span></div>`;
    }).join('');
    const count=state.buildings.filter(Boolean).length, free=6-count;
    $('active-facilities').innerHTML=`${count}<small> / 6</small>`;
    $('slots-label').textContent=`${free} FREE SLOT${free===1?'':'S'}`;
  }
  function facilityRates() {
    const rates={iron:0,silicon:0,alloy:0,cells:0,processors:0,segments:0};
    const count=type=>state.buildings.filter(x=>x===type).length;
    // Raw-material extraction runs from inexhaustible planetary and asteroid deposits.
    rates.iron += count('iron')*1.25; rates.silicon += count('silicon')*1.05;
    // Conversion lines have input caps; this keeps the production chain physically coherent.
    let foundry=count('foundry')*.48;
    foundry=Math.min(foundry, state.resources.iron/1.8);
    rates.iron-=foundry?count('foundry')*1.8:0;
    rates.alloy+=foundry;
    let solar=count('solar')*.65;
    solar=Math.min(solar,state.resources.silicon/1.0);
    rates.silicon-=solar?count('solar')*1.0:0;
    rates.cells+=solar;
    let circuit=count('circuit')*.18;
    circuit=Math.min(circuit,state.resources.silicon/.55,state.resources.alloy/.18);
    rates.silicon-=circuit?count('circuit')*.55:0; rates.alloy-=circuit?count('circuit')*.18:0; rates.processors+=circuit;
    let assembler=count('assembler')*.18;
    assembler=Math.min(assembler,state.resources.alloy/2.5,state.resources.cells/2,state.resources.processors);
    rates.alloy-=assembler?count('assembler')*2.5:0; rates.cells-=assembler?count('assembler')*2:0; rates.processors-=assembler?count('assembler'):0; rates.segments+=assembler;
    return rates;
  }
