const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({headless:true, executablePath:'/usr/bin/chromium', args:['--no-sandbox','--disable-dev-shm-usage']});
  const context = await browser.newContext({viewport:{width:1280,height:1050}, deviceScaleFactor:1});
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:3002');
  await page.waitForTimeout(500);
  const startup = await page.locator('#activity-list').innerText();
  const cycleStartup = await page.locator('#cycle').innerText();
  if (cycleStartup !== '001' || startup.includes('Cycle 000')) throw new Error(`bad startup: cycle=${cycleStartup}, log=${startup}`);
  await page.locator('[data-build="foundry"]').click();
  await page.locator('[data-build="solar"]').click();
  await page.waitForTimeout(3000);
  const manufactured = await page.evaluate(() => ({alloy:document.querySelector('#alloy').textContent,cells:document.querySelector('#cells').textContent,facilities:document.querySelector('#active-facilities').textContent,log:document.querySelector('#activity-list').innerText}));
  if (Number(manufactured.alloy) <= 0 || Number(manufactured.cells) <= 0 || !manufactured.log.includes('commissioned')) throw new Error(`manufacturing failed: ${JSON.stringify(manufactured)}`);
  await page.reload();
  await page.waitForTimeout(300);
  if (!(await page.locator('#active-facilities').innerText()).includes('4')) throw new Error('building autosave did not persist');

  await page.evaluate(() => {
    const save = JSON.parse(localStorage.getItem('helios-foundry-save-v1'));
    save.buildings = ['iron','silicon','foundry','solar','circuit','assembler'];
    save.resources = {iron:500,silicon:500,alloy:500,cells:500,processors:500,segments:0};
    save.panels = 0;
    save.elapsed = -2;
    save.cycle = 0;
    save.eventLog = [{stamp:'-1:-1',message:'<b>Cycle 000</b> invalid legacy log'}];
    localStorage.setItem('helios-foundry-save-v1', JSON.stringify(save));
  });
  await page.reload();
  await page.waitForTimeout(2500);
  const normalized = await page.evaluate(() => ({cycle:document.querySelector('#cycle').textContent,log:document.querySelector('#activity-list').innerText,segments:document.querySelector('#processors').textContent}));
  if (normalized.cycle !== '001' || normalized.log.includes('Cycle 000') || normalized.log.includes('-1:-1')) throw new Error(`bad legacy normalization: ${JSON.stringify(normalized)}`);
  const chain = await page.evaluate(() => ({iron:document.querySelector('#iron').textContent,silicon:document.querySelector('#silicon').textContent,alloy:document.querySelector('#alloy').textContent,cells:document.querySelector('#cells').textContent,processors:document.querySelector('#processors').textContent,stored:JSON.parse(localStorage.getItem('helios-foundry-save-v1')).resources.segments}));
  if (Number(chain.stored) <= 0) throw new Error(`production chain did not assemble segments: ${JSON.stringify(chain)}`);

  await page.evaluate(() => {
    const save=JSON.parse(localStorage.getItem('helios-foundry-save-v1'));
    save.resources.segments=72; save.panels=0; localStorage.setItem('helios-foundry-save-v1',JSON.stringify(save));
  });
  await page.reload();
  await page.waitForTimeout(300);
  for(let i=0;i<72;i++) await page.locator('#deploy-button').click();
  const completion = await page.evaluate(() => ({panels:document.querySelector('#progress-label').innerText,directive:document.querySelector('#directive').innerText,button:document.querySelector('#deploy-button').disabled,log:document.querySelector('#activity-list').innerText}));
  if (!completion.panels.startsWith('72') || completion.button !== true || completion.directive !== 'A star, made yours') throw new Error(`completion failed: ${JSON.stringify(completion)}`);
  await page.reload(); await page.waitForTimeout(300);
  const persisted = await page.locator('#progress-label').innerText();
  if (!persisted.startsWith('72')) throw new Error(`completion did not persist: ${persisted}`);
  await page.screenshot({path:'/tmp/opencode/helios-fixed.jpg',type:'jpeg',quality:78,fullPage:true});
  console.log(JSON.stringify({startup:{cycle:cycleStartup,log:startup},manufactured,normalized,chain,completion,persisted,errors},null,2));
  await browser.close();
})().catch(error=>{console.error(error);process.exit(1)});
NODE

